mapper.select:
SELECT DISTINCT l.`dkmc` FROM `t_land` l
WHERE l.`del_flag` = 0 AND l.`dkmc` IS NOT NULL AND TRIM(l.`dkmc`) != ''
ORDER BY l.`dkmc` ASC LIMIT #{limit}

SELECT DISTINCT l.`xzqh` FROM `t_land` l
WHERE l.`del_flag` = 0 AND l.`xzqh` IS NOT NULL AND TRIM(l.`xzqh`) != ''
ORDER BY l.`xzqh` ASC LIMIT #{limit}

SELECT DISTINCT l.`srr` FROM `t_land` l
WHERE l.`del_flag` = 0 AND l.`srr` IS NOT NULL AND TRIM(l.`srr`) != ''
ORDER BY l.`srr` ASC LIMIT #{limit}

SELECT DISTINCT YEAR(l.`crsj`) AS y FROM `t_land` l
WHERE l.`del_flag` = 0 AND l.`crsj` IS NOT NULL
ORDER BY y DESC LIMIT #{limit}

SELECT DISTINCT f.`ptxmmc` FROM `t_supporting_facilities` f
WHERE COALESCE(f.`delFlag`, '0') = '0' AND f.`ptxmmc` IS NOT NULL AND TRIM(f.`ptxmmc`) != ''
ORDER BY f.`ptxmmc` ASC LIMIT #{limit}

SELECT DISTINCT f.`ptsslb` FROM `t_supporting_facilities` f
WHERE COALESCE(f.`delFlag`, '0') = '0' AND f.`ptsslb` IS NOT NULL AND TRIM(f.`ptsslb`) != ''
ORDER BY f.`ptsslb` ASC LIMIT #{limit}

SELECT DISTINCT f.`xzqh` FROM `t_supporting_facilities` f
WHERE COALESCE(f.`delFlag`, '0') = '0' AND f.`xzqh` IS NOT NULL AND TRIM(f.`xzqh`) != ''
ORDER BY f.`xzqh` ASC LIMIT #{limit}

SELECT DISTINCT f.`zjlsqk` FROM `t_supporting_facilities` f
WHERE COALESCE(f.`delFlag`, '0') = '0' AND f.`zjlsqk` IS NOT NULL AND TRIM(f.`zjlsqk`) != ''
ORDER BY f.`zjlsqk` ASC LIMIT #{limit}
